<script setup>
import {computed,nextTick,onBeforeUnmount,ref,watch} from 'vue'
import L from 'leaflet'
import 'leaflet/dist/leaflet.css'
import markerIcon from 'leaflet/dist/images/marker-icon.png'
import markerRetina from 'leaflet/dist/images/marker-icon-2x.png'
import markerShadow from 'leaflet/dist/images/marker-shadow.png'
import {isBlankValue,validIncidentPosition} from '../../data/incidentWeather.js'
const props=defineProps({model:{type:Object,required:true}})
watch(()=>props.model,model=>{for(const [key,value] of Object.entries({lat:null,lon:null,positionQuality:'unknown',province:'',region:'',nearestPorts:''}))if(model[key]===undefined)model[key]=value},{immediate:true})
const mapOpen=ref(false),mapElement=ref(null),draftLat=ref(null),draftLon=ref(null),mapError=ref('')
let map=null,marker=null,resizeTimer=null
const hasDraft=computed(()=>validIncidentPosition(draftLat.value,draftLon.value))
const qualityOptions=[{label:'Reported position',value:'reported'},{label:'Approximate position',value:'approximate'},{label:'Unknown / unlocated',value:'unknown'}]
const coordinateRule=(value,limit)=>isBlankValue(value)||(Number.isFinite(Number(value))&&Math.abs(Number(value))<=limit)||`Enter a number between −${limit} and ${limit}, or leave blank.`
const coordinateIssue=computed(()=>{const {lat,lon}=props.model;if(isBlankValue(lat)&&isBlankValue(lon))return '';return validIncidentPosition(lat,lon)?'':'Enter both valid coordinates, or leave both blank.'})
function openPicker(){draftLat.value=isBlankValue(props.model.lat)?null:props.model.lat;draftLon.value=isBlankValue(props.model.lon)?null:props.model.lon;mapError.value='';mapOpen.value=true}
function enteredCoordinates(){if(props.model.positionQuality==='unknown'&&validIncidentPosition(props.model.lat,props.model.lon))props.model.positionQuality='approximate'}
function pick(lat,lon){draftLat.value=Number(lat.toFixed(6));draftLon.value=Number((((lon+180)%360+360)%360-180).toFixed(6));placeMarker()}
function placeMarker(){if(!map||!hasDraft.value)return;const point=[Number(draftLat.value),Number(draftLon.value)];if(marker)marker.setLatLng(point);else{marker=L.marker(point,{draggable:true,icon:L.icon({iconUrl:markerIcon,iconRetinaUrl:markerRetina,shadowUrl:markerShadow,iconSize:[25,41],iconAnchor:[12,41],shadowSize:[41,41]})}).addTo(map);marker.on('dragend',()=>{const point=marker.getLatLng();pick(point.lat,point.lng)})}}
async function initializeMap(){await nextTick();if(!mapOpen.value||!mapElement.value||map)return;const point=hasDraft.value?[Number(draftLat.value),Number(draftLon.value)]:[12.8797,121.774];map=L.map(mapElement.value,{worldCopyJump:true}).setView(point,hasDraft.value?10:5);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'}).on('tileerror',()=>{mapError.value='The base map could not load. You can still enter coordinates manually.'}).addTo(map);placeMarker();map.on('click',event=>pick(event.latlng.lat,event.latlng.lng));resizeTimer=setTimeout(()=>map?.invalidateSize(),150)}
function destroyMap(){clearTimeout(resizeTimer);map?.remove();map=null;marker=null}
function centerPoint(){if(map&&hasDraft.value){placeMarker();map.setView([Number(draftLat.value),Number(draftLon.value)],10)}}
function applyPoint(){if(!hasDraft.value)return;props.model.lat=Number(draftLat.value);props.model.lon=Number(draftLon.value);props.model.positionQuality='approximate';mapOpen.value=false}
watch([draftLat,draftLon],()=>placeMarker())
onBeforeUnmount(destroyMap)
</script>
<template><section class="incident-location">
 <div class="row items-center q-mb-md"><div class="col"><div class="section-label">Location details</div><div class="text-caption text-blue-grey-6">Enter the reported location. Office jurisdiction is selected separately.</div></div><q-btn outline color="primary" no-caps icon="pin_drop" label="Select Location on Map" @click="openPicker"/></div>
 <div class="form-grid"><q-select v-model="model.positionQuality" :options="qualityOptions" emit-value map-options outlined dense class="span-2" label="Coordinate quality"/><q-input v-model.number="model.lat" @update:model-value="enteredCoordinates" outlined dense type="number" step="any" label="Latitude" :rules="[value=>coordinateRule(value,90)]" hint="Blank means unknown; zero is valid."/><q-input v-model.number="model.lon" @update:model-value="enteredCoordinates" outlined dense type="number" step="any" label="Longitude" :rules="[value=>coordinateRule(value,180)]" hint="Choose reported or approximate when a position is known."/><q-input v-model="model.region" outlined dense label="Region"/><q-input v-model="model.province" outlined dense label="Province"/><q-input v-model="model.nearestPorts" outlined dense class="span-2" label="Nearest Port(s)" hint="Enter reported port names; no port or region is inferred from the map."/></div>
 <q-banner v-if="coordinateIssue" dense class="bg-orange-1 text-dark q-mt-sm" role="alert">{{coordinateIssue}}</q-banner>
 <q-dialog v-model="mapOpen" backdrop-filter="blur(4px)" @show="initializeMap" @hide="destroyMap"><q-card class="location-dialog"><q-card-section class="row items-center text-white q-py-md map-heading"><div class="text-subtitle1 text-weight-bold"><q-icon name="pin_drop" class="q-mr-sm"/>Select Location on Map</div><q-space/><q-btn flat round icon="close" color="white" v-close-popup aria-label="Close map picker"/></q-card-section>
 <q-card-section class="q-pa-none map-canvas-section"><div ref="mapElement" class="map-canvas" aria-label="Incident location map"/><div class="coordinates-floating-badge"><strong>Selected:</strong> Lat {{isBlankValue(draftLat)?'—':draftLat}}, Long {{isBlankValue(draftLon)?'—':draftLon}}</div></q-card-section>
 <q-card-section class="q-py-sm"><p class="text-caption text-blue-grey-6 q-mb-sm">Click the map, drag the pin, or enter coordinates. Applying a map point marks it approximate.</p><q-banner v-if="mapError" dense class="bg-orange-1 text-dark q-mb-sm">{{mapError}}</q-banner><div class="form-grid"><q-input v-model.number="draftLat" outlined stack-label type="number" step="any" label="Selected latitude"/><q-input v-model.number="draftLon" outlined stack-label type="number" step="any" label="Selected longitude"/></div></q-card-section>
 <q-card-actions align="right" class="q-pa-md"><q-btn flat color="primary" no-caps label="Center map on coordinates" :disable="!hasDraft" @click="centerPoint"/><q-space/><q-btn flat color="grey-7" no-caps label="Cancel" v-close-popup/><q-btn unelevated color="primary" no-caps label="Apply Coordinates" :disable="!hasDraft" @click="applyPoint"/></q-card-actions></q-card></q-dialog>
</section></template>
<style scoped>
.incident-location{font-family:'Hanken Grotesk',sans-serif}.section-label{font-size:15px;font-weight:700;color:#002147}.location-dialog{width:800px;max-width:94vw;border-radius:12px;overflow:hidden}.map-heading{background:#002147}.map-canvas-section{height:360px;position:relative}.map-canvas{width:100%;height:100%}.coordinates-floating-badge{position:absolute;top:16px;left:50%;transform:translateX(-50%);z-index:1000;background:rgba(255,255,255,.92);padding:8px 16px;border-radius:8px;border:1px solid #e2e8f0;box-shadow:0 4px 12px rgba(0,0,0,.1);font-size:13px;color:#0f172a;pointer-events:none;white-space:nowrap}:deep(.q-field--outlined .q-field__control){border-radius:8px;background:#fff}:deep(.q-field--outlined .q-field__control:before){border-color:#cbd5e1}:deep(.q-field--outlined.q-field--focused .q-field__control:after){border-color:#002147}@media(max-width:599px){.map-canvas-section{height:280px}.coordinates-floating-badge{font-size:11px;max-width:95%;padding:7px 9px}.incident-location>.row{gap:10px}.location-dialog :deep(.q-card__actions){gap:6px}}:global(.body--dark) .section-label{color:#cbd5e1}:global(.body--dark) .incident-location :deep(.q-field--outlined .q-field__control){background:#0f172a}
</style>
